PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,phone TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,full_name TEXT NOT NULL,birth_date TEXT,avatar TEXT,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,icon TEXT NOT NULL DEFAULT 'building',color TEXT NOT NULL DEFAULT '#0f766a',layout TEXT NOT NULL DEFAULT 'cards' CHECK(layout IN ('cards','list')),supports_duty INTEGER NOT NULL DEFAULT 0,kind TEXT NOT NULL DEFAULT 'general' CHECK(kind IN ('general','pharmacy','doctor','station','transport')),sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS areas(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,scope TEXT NOT NULL DEFAULT 'city' CHECK(scope IN ('city','rural')));
CREATE TABLE IF NOT EXISTS services(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(id),area_id INTEGER NOT NULL REFERENCES areas(id),owner_id INTEGER REFERENCES users(id),address TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',whatsapp TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',details TEXT NOT NULL DEFAULT '{}',schedule TEXT NOT NULL DEFAULT '[]',override_status TEXT CHECK(override_status IN ('open','closed')),override_until TEXT,duty_until TEXT,approval TEXT NOT NULL DEFAULT 'pending' CHECK(approval IN ('pending','approved','rejected')),rejection_reason TEXT NOT NULL DEFAULT '',source_url TEXT NOT NULL DEFAULT '',source_checked_at TEXT,updated_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS services_filter ON services(approval,category_id,area_id);
CREATE INDEX IF NOT EXISTS services_owner ON services(owner_id);
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,entity_id INTEGER,created_at TEXT NOT NULL);
